using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEditor;
using UnityEditor.SceneManagement;
using Skybreak.World;
public static class InstallFinalTeleportVisual
{
    public static string Main(){
        var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlaying||Lightmapping.isRunning||scene.path!="Assets/Scenes/GameLevel/SkybreakMain.unity")throw new Exception("Use main scene in Edit Mode outside a lighting bake.");
        var shrine=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).Single(t=>t.name=="AuroraReactorShrine");var crystal=shrine.GetComponentsInChildren<MeshRenderer>().Single(r=>r.name=="Suspended_FacetedCrystal");
        var project=Path.GetDirectoryName(Application.dataPath);var backup=Path.Combine(project,"Tools/SceneSnapshots/SkybreakMain_before_final_teleport_visual_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity");if(!EditorSceneManager.SaveScene(scene,backup,true))throw new Exception("Backup failed");
        var fieldShader=Shader.Find("Skybreak/Final Teleport Field");if(fieldShader==null||ShaderUtil.ShaderHasError(fieldShader))throw new Exception("Teleport field shader did not compile");
        var crystalPath="Assets/Materials/Environment/Decoration/Custom/AuroraArchitecture/FinalTeleportCrystal.mat";var crystalMaterial=AssetDatabase.LoadAssetAtPath<Material>(crystalPath);if(crystalMaterial==null){crystalMaterial=new Material(crystal.sharedMaterial);AssetDatabase.CreateAsset(crystalMaterial,crystalPath);}
        crystalMaterial.SetColor("_BaseColor",new Color(.13f,.63f,.72f));crystalMaterial.SetFloat("_Metallic",.15f);crystalMaterial.SetFloat("_Smoothness",.82f);crystalMaterial.EnableKeyword("_EMISSION");crystalMaterial.SetColor("_EmissionColor",new Color(.12f,.75f,1)*.6f);crystalMaterial.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;EditorUtility.SetDirty(crystalMaterial);
        var fieldPath="Assets/Materials/Environment/Decoration/Custom/AuroraArchitecture/FinalTeleportField.mat";var fieldMaterial=AssetDatabase.LoadAssetAtPath<Material>(fieldPath);if(fieldMaterial==null){fieldMaterial=new Material(fieldShader);AssetDatabase.CreateAsset(fieldMaterial,fieldPath);}
        fieldMaterial.SetColor("_Tint",new Color(.08f,.68f,1));fieldMaterial.SetColor("_Accent",new Color(.48f,.15f,.88f));fieldMaterial.SetFloat("_Energy",.8f);fieldMaterial.SetFloat("_Opacity",.6f);fieldMaterial.SetVector("_PulseOrigin",new Vector4(.5f,.60f,0,0));EditorUtility.SetDirty(fieldMaterial);
        var meshPath="Assets/Models/Environment/Dungeon/Meshes/FinalTeleportFieldQuad.asset";var quad=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(quad==null){quad=new Mesh{name="FinalTeleportFieldQuad"};quad.vertices=new[]{new Vector3(-.5f,-.5f,0),new Vector3(.5f,-.5f,0),new Vector3(.5f,.5f,0),new Vector3(-.5f,.5f,0)};quad.uv=new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up};quad.triangles=new[]{0,2,1,0,3,2};quad.RecalculateNormals();quad.RecalculateBounds();AssetDatabase.CreateAsset(quad,meshPath);}
