        var field=group.Cast<Transform>().FirstOrDefault(t=>t.name=="Transparent radiating aperture");if(field==null){var go=new GameObject("Transparent radiating aperture");go.transform.SetParent(group,false);Undo.RegisterCreatedObjectUndo(go,"Radiating field");go.AddComponent<MeshFilter>();go.AddComponent<MeshRenderer>();field=go.transform;}
        Undo.RecordObject(field,"Inside arch behind crystal");field.SetPositionAndRotation(new Vector3(42,3.35f,95.8f),Quaternion.Euler(0,180,0));field.localScale=new Vector3(4.35f/1.35f,4.6f/1.35f,1);field.GetComponent<MeshFilter>().sharedMesh=quad;var r=field.GetComponent<MeshRenderer>();r.sharedMaterial=fieldMaterial;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;r.lightProbeUsage=LightProbeUsage.Off;r.reflectionProbeUsage=ReflectionProbeUsage.Off;GameObjectUtility.SetStaticEditorFlags(field.gameObject,0);
        var lightTransform=group.Cast<Transform>().FirstOrDefault(t=>t.name=="Final crystal cyan spill / baked");if(lightTransform==null){var go=new GameObject("Final crystal cyan spill / baked");go.transform.SetParent(group,false);go.AddComponent<Light>();Undo.RegisterCreatedObjectUndo(go,"Final crystal light");lightTransform=go.transform;}
        var light=lightTransform.GetComponent<Light>();light.transform.position=crystal.bounds.center+Vector3.back*.86f;light.type=LightType.Point;light.color=new Color(.12f,.75f,1);light.intensity=1.5f;light.range=5.5f;light.lightmapBakeType=LightmapBakeType.Baked;light.shadows=LightShadows.None;
        var visual=group.GetComponent<FinalTeleportVisual>();if(visual==null)visual=Undo.AddComponent<FinalTeleportVisual>(group.gameObject);var so=new SerializedObject(visual);so.FindProperty("energyField").objectReferenceValue=r;so.FindProperty("crystal").objectReferenceValue=crystal;var player=UnityEngine.Object.FindAnyObjectByType<Skybreak.Descent.DescentCharacterController>();so.FindProperty("player").objectReferenceValue=player!=null?player.transform:null;so.FindProperty("powered").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(visual);
