        var dir=Path.Combine(project,"Docs/GV/LevelDesign/Reports/FinalTeleportPoint");Directory.CreateDirectory(dir);var report="Final return-point visual installed in the existing Aurora reactor shrine.\nDedicated cyan shiny/emissive crystal material; original crystal geometry and pillar materials retained.\nTransparent cyan/violet ripples behind the crystal, within the stone arch: centre (42,3.35,95.8), width 4.35m / height 4.6m.\nAnimated unlit two-triangle field, no collider/shadow/depth writing, excluded from baked GI.\nOne additional baked cyan spill: intensity 1.5 / range 5.5m.\nFinalTeleportVisual gently pulses crystal emission; field brightens within 12m and reaches full proximity strength at 4m.\nSetPowered(bool) is provided for future encounter/quest logic. No player teleport or quest completion is implemented by this visual.\nBackup: "+backup;File.WriteAllText(Path.Combine(dir,"Installation.txt"),report);return report;
    }
